#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<int> largestPower(vector<int>& a){
        vector<vector<int>> groups(1,a);vector<int>ans;
        for(int b=14;b>=0;b--){
            int prefix=0;vector<vector<int>>next;bool split=false;
            for(auto &g:groups){
                if(split){next.push_back(g);continue;}
                vector<int>yes,no;
                for(int x:g)((x>>b)&1?yes:no).push_back(x);
                if(no.empty()){prefix+=g.size();next.push_back(g);}
                else{
                    prefix+=yes.size();if(!yes.empty())next.push_back(yes);
                    next.push_back(no);split=true;
                }
            }
            ans.push_back(prefix);groups.swap(next);
        }
        return ans;
    }
};
